// Auto-compute totals from projetos
const _emAndamento = projetos.filter(p => p.status === "Em Andamento" || p.status === "Atrasado").length;
const _budgetSum = projetos.reduce((s, p) => s + p.budget, 0);
const _comBC = projetos.filter(p => ["Ativo EPP","Projeto Concluído","Validado"].includes(p.statusBC)).length;
const _offTrack = projetos.filter(p => p.status === "Atrasado").length;
totaisPortfolio.ativos = _emAndamento;
totaisPortfolio.budgetTotal = _budgetSum;
totaisPortfolio.bcAprovadoPct = Math.round((_comBC / projetos.length) * 100);
totaisPortfolio.offTrack = _offTrack;
